import { JSONValue, jsonGet, jsonString, jsonPretty } from './claude-events';

export type ChatRole = 'user' | 'assistant' | 'system';
export type AgentProvider = 'claude' | 'codex' | 'codexAppServer';

export type ChatStatus = 'idle' | 'connecting' | 'streaming' | 'reconnecting' | 'error';

/**
 * A conversation that lives on the sprite's disk rather than in the phone's local
 * chat store — i.e. one started from the "sprite console" CLI (`claude` / `codex`)
 * on a computer. Discovered by scanning the sprite's transcript files, it can be
 * pulled into the conversation list and resumed in the chat UI. Shape is the
 * common denominator of Claude/Codex session summaries plus the provider tag.
 */
export interface RemoteAgentSession {
  /** Session/thread id — the value passed to `claude --resume` / `codex resume`. */
  id: string;
  provider: AgentProvider;
  /** Working directory the session ran in (resume must reuse it). */
  cwd?: string;
  /** First user prompt, trimmed — used as the list preview. */
  preview: string;
  /** Number of transcript lines (rough activity indicator). */
  messageCount: number;
  /** Transcript file mtime in ms since epoch. */
  modified: number;
  /** True when the CLI session is (likely) still running. */
  live: boolean;
}

export interface ChatMessage {
  id: string;
  timestamp: number;
  role: ChatRole;
  content: ChatContent[];
  checkpointId?: string;
  checkpointComment?: string;
}

export type ChatContent =
  | { type: 'text'; text: string }
  | { type: 'reasoning'; text: string }
  | { type: 'toolUse'; card: ToolUseCard }
  | { type: 'toolResult'; card: ToolResultCard }
  | { type: 'error'; message: string }
  | { type: 'turnOutcome'; outcome: TurnOutcome };

export type TurnOutcomeStatus = 'success' | 'maxTurns' | 'error' | 'interrupted';

/**
 * How a turn ended — from Claude's `result` event (`subtype`/`is_error`),
 * Codex's `turn.completed`/`error`, or a local interrupt. Rendered as a footer
 * on the assistant message so a silent stop is distinguishable from success.
 */
export interface TurnOutcome {
  status: TurnOutcomeStatus;
  /** Raw CLI result subtype (e.g. `error_max_turns`) when one was reported. */
  subtype?: string;
  durationMs?: number;
  numTurns?: number;
  completedAt: number;
}

export function formatTurnDuration(ms: number | undefined): string | null {
  if (ms === undefined || !Number.isFinite(ms) || ms < 0) return null;
  const seconds = ms / 1000;
  if (seconds < 1) return '<1s';
  if (seconds < 60) return `${Math.floor(seconds)}s`;
  const m = Math.floor(seconds / 60);
  const s = Math.floor(seconds % 60);
  return `${m}m ${s}s`;
}

export interface ToolUseCard {
  toolUseId: string;
  toolName: string;
  input: JSONValue;
  startedAt: number;
  result?: ToolResultCard;
}

export interface ToolResultCard {
  toolUseId: string;
  toolName: string;
  content: JSONValue;
  completedAt: number;
}

export function toolUseSummary(card: ToolUseCard): string {
  const input = card.input;
  switch (card.toolName) {
    case 'Bash':
      return jsonString(jsonGet(input, 'command')) ?? 'bash command';
    case 'Read':
      return jsonString(jsonGet(input, 'file_path')) ?? 'read file';
    case 'Write':
      return jsonString(jsonGet(input, 'file_path')) ?? 'write file';
    case 'Edit':
      return jsonString(jsonGet(input, 'file_path')) ?? 'edit file';
    case 'Glob':
      return jsonString(jsonGet(input, 'pattern')) ?? 'glob search';
    case 'Grep':
      return jsonString(jsonGet(input, 'pattern')) ?? 'grep search';
    case 'WebSearch':
      return jsonString(jsonGet(input, 'query')) ?? 'web search';
    case 'TodoWrite': {
      const todos = jsonGet(input, 'todos');
      if (Array.isArray(todos)) {
        const total = todos.length;
        const done = todos.filter(
          (t) => jsonString(jsonGet(t, 'status')) === 'completed'
        ).length;
        return `${done}/${total} tasks`;
      }
      return 'update plan';
    }
    default:
      return card.toolName;
  }
}

export function toolUseIcon(toolName: string): string {
  switch (toolName) {
    case 'Bash': return '>';
    case 'Read': return '📄';
    case 'Write': return '📝';
    case 'Edit': return '✏️';
    case 'Glob': return '🔍';
    case 'Grep': return '🔎';
    case 'WebSearch': return '🌐';
    case 'TodoWrite': return '📋';
    default: return '🔧';
  }
}

export function toolUseActivityLabel(card: ToolUseCard, cwd?: string): string {
  const relativize = (s: string) => {
    if (cwd && s.startsWith(cwd)) {
      const rel = s.slice(cwd.length);
      return rel.startsWith('/') ? rel.slice(1) : rel;
    }
    return s;
  };
  const input = card.input;
  switch (card.toolName) {
    case 'Bash': {
      const cmd = jsonString(jsonGet(input, 'command')) ?? 'command';
      return `Running ${cmd.slice(0, 60)}...`;
    }
    case 'Read': {
      const fp = jsonString(jsonGet(input, 'file_path')) ?? 'file';
      return `Reading ${relativize(fp.split('/').pop() ?? fp)}...`;
    }
    case 'Write': {
      const fp = jsonString(jsonGet(input, 'file_path')) ?? 'file';
      return `Writing ${relativize(fp.split('/').pop() ?? fp)}...`;
    }
    case 'Edit': {
      const fp = jsonString(jsonGet(input, 'file_path')) ?? 'file';
      return `Editing ${relativize(fp.split('/').pop() ?? fp)}...`;
    }
    case 'Glob': {
      const pattern = jsonString(jsonGet(input, 'pattern')) ?? 'files';
      return `Searching ${pattern}...`;
    }
    case 'Grep': {
      const pattern = jsonString(jsonGet(input, 'pattern')) ?? 'code';
      return `Searching ${pattern}...`;
    }
    case 'WebSearch': {
      const query = jsonString(jsonGet(input, 'query')) ?? 'web';
      return `Searching the web for ${query.slice(0, 40)}...`;
    }
    case 'TodoWrite':
      return 'Updating plan...';
    default:
      return `Running ${card.toolName}...`;
  }
}

export function toolElapsedString(card: ToolUseCard): string | null {
  if (!card.result) return null;
  const elapsed = (card.result.completedAt - card.startedAt) / 1000;
  if (elapsed < 1) return '<1s';
  if (elapsed < 60) return `${Math.floor(elapsed)}s`;
  const m = Math.floor(elapsed / 60);
  const s = Math.floor(elapsed % 60);
  return `${m}m ${s}s`;
}

export function toolResultDisplayContent(card: ToolResultCard): string {
  const { content } = card;
  if (typeof content === 'string') return content;
  if (Array.isArray(content)) {
    const strings = content.filter((x): x is string => typeof x === 'string');
    if (strings.length > 0) return strings.join('\n');
    const texts = content
      .filter((x): x is Record<string, JSONValue> => typeof x === 'object' && x !== null && !Array.isArray(x))
      .map((x) => typeof x.text === 'string' ? x.text : null)
      .filter((x): x is string => x !== null);
    if (texts.length > 0) return texts.join('\n');
    return jsonPretty(content);
  }
  return jsonPretty(content);
}

export function makeId(): string {
  return Math.random().toString(36).slice(2) + Date.now().toString(36);
}

export function providerDisplayName(provider: AgentProvider): string {
  switch (provider) {
    case 'codex':
      return 'Codex';
    case 'codexAppServer':
      return 'Codex Server';
    default:
      return 'Claude';
  }
}

export function isCodexProvider(provider: AgentProvider): boolean {
  return provider === 'codex' || provider === 'codexAppServer';
}
import AsyncStorage from '@react-native-async-storage/async-storage';
import { AgentProvider, ChatMessage } from '@/models/chat';
import { Database, getDatabase } from './database';

/**
 * Repository layer for the chat domain.
 *
 * Replaces the old AsyncStorage `loadChatList`/`saveChatList`/`loadChatMessages`
 * calls with a typed, row-oriented API backed by SQLite. Each chat is its own
 * row, so a single chat can be updated atomically without rewriting a whole
 * JSON list — and queries like "all chats with an active run" become trivial.
 *
 * On first launch, existing AsyncStorage data (`sprite_chats_*` / `chat_meta_*`)
 * is imported once, then SQLite is the only read path.
 */

// MARK: - Types

export interface PersistedChat {
  id: string;
  spriteName: string;
  chatNumber: number;
  customName?: string;
  provider: AgentProvider;
  claudeSessionId?: string;
  codexSessionId?: string;
  currentServiceName?: string;
  workingDirectory: string;
  createdAt: number;
  lastUsed: number;
  isClosed: boolean;
  firstMessagePreview?: string;
  lastSessionComplete: boolean;
  processedEventUUIDs: string[];
  activeRun?: ActiveChatRun;
}

export interface ActiveChatRun {
  execSessionId: string;
  taskName: string;
  provider: AgentProvider;
  transport?: 'exec' | 'codexAppServer';
  userMessageId: string;
  assistantMessageId: string;
  workingDirectory: string;
  startedAt: number;
}

// MARK: - Normalization (defensive load-time sanitization)

function normalizeProvider(value: unknown): AgentProvider {
  if (value === 'codexAppServer') return 'codexAppServer';
  return value === 'codex' ? 'codex' : 'claude';
}

export function normalizePersistedChat(value: unknown): PersistedChat {
  const raw = (value ?? {}) as Partial<PersistedChat> & Record<string, unknown>;
  return {
    id: String(raw.id ?? ''),
    spriteName: String(raw.spriteName ?? ''),
    chatNumber: Number(raw.chatNumber ?? 1),
    customName: typeof raw.customName === 'string' ? raw.customName : undefined,
    provider: normalizeProvider(raw.provider),
    claudeSessionId: typeof raw.claudeSessionId === 'string' ? raw.claudeSessionId : undefined,
    codexSessionId: typeof raw.codexSessionId === 'string' ? raw.codexSessionId : undefined,
    currentServiceName:
      typeof raw.currentServiceName === 'string' ? raw.currentServiceName : undefined,
    workingDirectory: String(raw.workingDirectory ?? ''),
    createdAt: Number(raw.createdAt ?? Date.now()),
    lastUsed: Number(raw.lastUsed ?? Date.now()),
    isClosed: Boolean(raw.isClosed),
    firstMessagePreview:
      typeof raw.firstMessagePreview === 'string' ? raw.firstMessagePreview : undefined,
    lastSessionComplete: raw.lastSessionComplete !== false,
    processedEventUUIDs: Array.isArray(raw.processedEventUUIDs)
      ? raw.processedEventUUIDs.filter((x): x is string => typeof x === 'string')
      : [],
    activeRun: normalizeActiveRun(raw.activeRun),
  };
}

function normalizeActiveRun(value: unknown): ActiveChatRun | undefined {
  if (!value || typeof value !== 'object') return undefined;
  const raw = value as Partial<ActiveChatRun> & Record<string, unknown>;
  if (
    typeof raw.execSessionId !== 'string' ||
    typeof raw.taskName !== 'string' ||
    typeof raw.userMessageId !== 'string' ||
    typeof raw.assistantMessageId !== 'string'
  ) {
    return undefined;
  }
  return {
    execSessionId: raw.execSessionId,
    taskName: raw.taskName,
    provider: normalizeProvider(raw.provider),
    transport: raw.transport === 'codexAppServer' ? 'codexAppServer' : 'exec',
    userMessageId: raw.userMessageId,
    assistantMessageId: raw.assistantMessageId,
    workingDirectory: typeof raw.workingDirectory === 'string' ? raw.workingDirectory : '',
    startedAt: Number(raw.startedAt ?? Date.now()),
  };
}

// MARK: - Row <-> object mapping

interface ChatRow {
  id: string;
  sprite_name: string;
  chat_number: number;
  provider: string;
  custom_name: string | null;
  claude_session_id: string | null;
  codex_session_id: string | null;
  current_service_name: string | null;
  working_directory: string;
  created_at: number;
  last_used: number;
  is_closed: number;
  first_message_preview: string | null;
  last_session_complete: number;
  processed_event_uuids: string;
}

interface ActiveRunRow {
  chat_id: string;
  exec_session_id: string;
  task_name: string;
  provider: string;
  transport: string;
  user_message_id: string;
  assistant_message_id: string;
  working_directory: string;
  started_at: number;
}

function rowToActiveRun(row: ActiveRunRow): ActiveChatRun {
  return {
    execSessionId: row.exec_session_id,
    taskName: row.task_name,
    provider: normalizeProvider(row.provider),
    transport: row.transport === 'codexAppServer' ? 'codexAppServer' : 'exec',
    userMessageId: row.user_message_id,
    assistantMessageId: row.assistant_message_id,
    workingDirectory: row.working_directory,
    startedAt: row.started_at,
  };
}

function rowToChat(row: ChatRow, activeRun?: ActiveChatRun): PersistedChat {
  return {
    id: row.id,
    spriteName: row.sprite_name,
    chatNumber: row.chat_number,
    provider: normalizeProvider(row.provider),
    customName: row.custom_name ?? undefined,
    claudeSessionId: row.claude_session_id ?? undefined,
    codexSessionId: row.codex_session_id ?? undefined,
    currentServiceName: row.current_service_name ?? undefined,
    workingDirectory: row.working_directory,
    createdAt: row.created_at,
    lastUsed: row.last_used,
    isClosed: Boolean(row.is_closed),
    firstMessagePreview: row.first_message_preview ?? undefined,
    lastSessionComplete: Boolean(row.last_session_complete),
    processedEventUUIDs: safeParseStringArray(row.processed_event_uuids),
    activeRun,
  };
}

function safeParseStringArray(raw: string): string[] {
  try {
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed.filter((x): x is string => typeof x === 'string') : [];
  } catch {
    return [];
  }
}

