            onPress={onSend}
            disabled={!canSend}
            hitSlop={8}
          >
            <Text style={[styles.sendIcon, { opacity: canSend ? 1 : 0.4 }]}>↑</Text>
          </Pressable>
        )}
      </View>
    </View>
  );
}

