            autoCorrect={false}
            secureTextEntry
          />
        </View>
        <Pressable
          style={({ pressed }) => [styles.row, { opacity: pressed ? 0.6 : 1 }]}
          disabled={savingGitHub || !githubTokenInput.trim()}
          onPress={handleSaveGitHubToken}
        >
          <Text
            style={[
              styles.rowLabel,
              { color: githubTokenInput.trim() ? colors.tint : colors.textSecondary },
